<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$o=getopt('',['company:','operator:','deliver-webhooks']);$company=filter_var($o['company']??null,FILTER_VALIDATE_INT);$operator=filter_var($o['operator']??null,FILTER_VALIDATE_INT);
if(!$company||!$operator){fwrite(STDERR,"Usage: php bin/run-operations-hub.php --company=ID --operator=SERVICE_USER_ID [--deliver-webhooks]\n");exit(2);}
\Dotenv\Dotenv::createImmutable(dirname(__DIR__))->safeLoad();$app=\Sentinel\Core\Application::create(dirname(__DIR__))->bootstrap();$authorised=false;$started=gmdate('Y-m-d H:i:s');
try{$ctx=$app->runtimeContext();$ctx->setTenantId($company);$ctx->setUser((string)$operator);if(!$app->database()->fetch("SELECT user_id FROM users WHERE company_id=:company AND user_id=:user AND status='ACTIVE'",['company'=>$company,'user'=>$operator]))throw new \RuntimeException('Invalid operator.');$auth=$app->container()->make('authorization_service');$auth->requirePermission((string)$operator,'operational_alerts.manage');if((new \Sentinel\Repositories\PermissionRepository($app->database(),$ctx))->userHasPermission((string)$operator,'site_scope.restricted'))throw new \RuntimeException('Use an unrestricted tenant worker account.');$authorised=true;$result=$app->container()->make('operational_alert_service')->tick();$result['radio_cleanup']=$app->container()->make('radio_service')->purgeExpired();if(isset($o['deliver-webhooks'])){$auth->requirePermission((string)$operator,'integrations.deliver');$result['webhooks']=$app->container()->make('integration_centre_service')->deliver();}$app->database()->execute("INSERT INTO worker_runs(company_id,worker_name,started_at,finished_at,state,summary) VALUES(:company,'operations-hub',:start,:end,'OK','Operational sources evaluated; configured delivery attempts processed.')",['company'=>$company,'start'=>$started,'end'=>gmdate('Y-m-d H:i:s')]);echo json_encode($result,JSON_THROW_ON_ERROR).PHP_EOL;}catch(\Throwable){if($app->database()->inTransaction())$app->database()->rollBack();if($authorised)try{$app->container()->make('control_room_service')->recordWorkerFailure('operations-hub');}catch(\Throwable){}fwrite(STDERR,"Operations hub worker failed. Review the restricted logs and configured operator permissions.\n");exit(1);}
